pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(address caller, uint256 val) public {
        vm.assume(caller != address(0));

        bool ok1;
        vm.prank(caller);
        try c.SetMinSum(val) { ok1 = true; } catch { ok1 = false; }

        uint256 minAfterFirst = c.MinSum();

        bool ok2;
        vm.prank(caller);
        try c.SetMinSum(val + 1) { ok2 = true; } catch { ok2 = false; }

        assertTrue(ok2, "Reference should allow second SetMinSum call but mutant may revert");

    }
}
